// Map display names, indexed by map index (same numbering as
// save.data.CurrentMap_N and data.MapBon[i]). Read from the game's own
// CustomLists.MapDispName (regenerated by the updater), so new maps such as
// The Royal Castle (43), Ancient Fissure (323) and Molten Edge (324) appear
// without a hand-copied table going stale.
import { MapDispName } from "../arkh/stats/data/game/customlists.js";

export const MAP_NAMES: readonly string[] = (MapDispName as string[]).map(String);
